//! The same benchmark messages generated by prost, by Google's Rust protobuf
//! (upb kernel), and by Google's C++ protobuf, behind a C API.

use prost::Message;

pub mod prost_benchmarks {
    include!(concat!(env!("OUT_DIR"), "/benchmarks.rs"));

    pub mod proto2 {
        include!(concat!(env!("OUT_DIR"), "/benchmarks.proto2.rs"));
    }
    pub mod proto3 {
        include!(concat!(env!("OUT_DIR"), "/benchmarks.proto3.rs"));
    }
}

#[allow(clippy::all)]
pub mod upb {
    // protobuf-codegen writes its entry point next to the first input file
    include!(concat!(
        env!("OUT_DIR"),
        "/protobuf_generated/datasets/google_message1/proto2/generated.rs"
    ));

    pub mod proto2 {
        pub use super::datasets_google_message1_proto2_benchmark_message1_proto2_proto::GoogleMessage1;
        pub use super::datasets_google_message2_benchmark_message2_proto::GoogleMessage2;
    }
    pub mod proto3 {
        pub use super::datasets_google_message1_proto3_benchmark_message1_proto3_proto::GoogleMessage1;
    }
}

pub mod dataset {
    pub fn google_message1_proto2() -> &'static [u8] {
        include_bytes!("../../third_party/old_protobuf_benchmarks/datasets/google_message1/proto2/dataset.google_message1_proto2.pb")
    }

    pub fn google_message1_proto3() -> &'static [u8] {
        include_bytes!("../../third_party/old_protobuf_benchmarks/datasets/google_message1/proto3/dataset.google_message1_proto3.pb")
    }

    pub fn google_message2() -> &'static [u8] {
        include_bytes!("../../third_party/old_protobuf_benchmarks/datasets/google_message2/dataset.google_message2.pb")
    }
}

pub fn load_dataset(dataset: &[u8]) -> prost_benchmarks::BenchmarkDataset {
    prost_benchmarks::BenchmarkDataset::decode(dataset).unwrap()
}

/// Safe wrapper over the C API in `cpp/shim.cc`
pub mod cpp {
    use core::marker::PhantomData;
    use core::ptr::NonNull;

    /// Must match `Kind` in `cpp/shim.cc`
    #[repr(u32)]
    #[derive(Clone, Copy, Debug)]
    pub enum Kind {
        GoogleMessage1Proto2 = 0,
        GoogleMessage1Proto3 = 1,
        GoogleMessage2 = 2,
    }

    #[repr(C)]
    struct Slice {
        data: *const u8,
        len: usize,
    }

    #[repr(C)]
    struct RawDataset {
        _private: [u8; 0],
    }

    extern "C" {
        fn google_dataset_new(kind: Kind, payloads: *const Slice, len: usize) -> *mut RawDataset;
        fn google_dataset_free(dataset: *mut RawDataset);
        fn google_dataset_decode(
            dataset: *mut RawDataset,
            payloads: *const Slice,
            len: usize,
        ) -> bool;
        fn google_dataset_decode_arena(
            dataset: *mut RawDataset,
            payloads: *const Slice,
            len: usize,
        ) -> bool;
        fn google_dataset_merge(
            dataset: *mut RawDataset,
            payloads: *const Slice,
            len: usize,
        ) -> bool;
        fn google_dataset_encode(
            dataset: *const RawDataset,
            buf: *mut u8,
            capacity: usize,
        ) -> usize;
        fn google_dataset_encoded_len(dataset: *const RawDataset) -> usize;
    }

    /// The payloads of a dataset, and the C++ messages parsed from them.
    ///
    /// Each method runs over the whole dataset in a single FFI call.
    pub struct Dataset<'a> {
        raw: NonNull<RawDataset>,
        payloads: Vec<Slice>,
        _payloads: PhantomData<&'a [u8]>,
    }

    impl<'a> Dataset<'a> {
        /// Returns `None` if a payload fails to parse
        pub fn new(kind: Kind, payloads: &'a [Vec<u8>]) -> Option<Self> {
            let payloads = payloads
                .iter()
                .map(|payload| Slice {
                    data: payload.as_ptr(),
                    len: payload.len(),
                })
                .collect::<Vec<_>>();
            // SAFETY: every slice points to a payload that outlives this call
            let raw = unsafe { google_dataset_new(kind, payloads.as_ptr(), payloads.len()) };
            Some(Self {
                raw: NonNull::new(raw)?,
                payloads,
                _payloads: PhantomData,
            })
        }

        /// Parses every payload into a new message
        pub fn decode(&mut self) -> bool {
            // SAFETY: the payloads are borrowed for `'a`
            unsafe {
                google_dataset_decode(
                    self.raw.as_ptr(),
                    self.payloads.as_ptr(),
                    self.payloads.len(),
                )
            }
        }

        /// Parses every payload into a new message, allocated on a reused arena
        pub fn decode_arena(&mut self) -> bool {
            // SAFETY: the payloads are borrowed for `'a`
            unsafe {
                google_dataset_decode_arena(
                    self.raw.as_ptr(),
                    self.payloads.as_ptr(),
                    self.payloads.len(),
                )
            }
        }

        /// Parses every payload into the same reused message
        pub fn merge(&mut self) -> bool {
            // SAFETY: the payloads are borrowed for `'a`
            unsafe {
                google_dataset_merge(
                    self.raw.as_ptr(),
                    self.payloads.as_ptr(),
                    self.payloads.len(),
                )
            }
        }

        /// Replaces the content of `buf` with every message encoded, one after
        /// the other. Returns `false` if the capacity of `buf` is too small.
        pub fn encode(&self, buf: &mut Vec<u8>) -> bool {
            buf.clear();
            // SAFETY: the C++ side writes at most `capacity` bytes, and returns
            // how many of them it initialized
            unsafe {
                let len =
                    google_dataset_encode(self.raw.as_ptr(), buf.as_mut_ptr(), buf.capacity());
                buf.set_len(len);
            }
            !buf.is_empty()
        }

        /// The sum of the encoded length of every message
        pub fn encoded_len(&self) -> usize {
            // SAFETY: `raw` is valid until drop
            unsafe { google_dataset_encoded_len(self.raw.as_ptr()) }
        }
    }

    impl Drop for Dataset<'_> {
        fn drop(&mut self) {
            // SAFETY: `raw` was returned by `google_dataset_new` and is freed once
            unsafe { google_dataset_free(self.raw.as_ptr()) }
        }
    }
}
